input.command:
$log="$HOME\.claude\global-memory\transcripts\.errors.log"
$keep = Get-Content $log | Where-Object { $_ -notmatch 'compiler-(backlog|stale-lock)' }
if ($keep) { Set-Content -Path $log -Value $keep -Encoding utf8NoBOM } else { Clear-Content $log }
"--- errors.log now:"; Get-Content $log
$c="$HOME\.claude\claude-memory-compiler"
"--- compiler repo: " + (git -C $c rev-parse --is-inside-work-tree 2>&1) + " top=" + (git -C $c rev-parse --show-toplevel 2>&1)
git -C $c status --porcelain | Measure-Object | ForEach-Object { "dirty files: $($_.Count)" }

